  tools.exec_command({cmd:"rg -n \"createMemo:|createMemo\\s*=|MemoService\" web/src/connect web/src --glob '*.ts' --glob '*.tsx' | head -80; sed -n '1,45p' proto/api/v1/memo_service.proto","workdir":"/bench/repo","yield_time_ms":10000,"max_output_tokens":10000})
